"use client";

import { useState } from "react";

export default function Home() {
  const [message, setMessage] = useState("");

  return (
    <main style={{
      minHeight: "100vh",
      background: "#080611",
      color: "white",
      padding: "30px",
      fontFamily: "Arial"
    }}>
      <h1 style={{ color: "#a855f7" }}>🤖 RoboDegen</h1>
      <p>AI Crypto Agent Intelligence</p>

      <div style={{
        marginTop: "50px",
        maxWidth: "650px",
        marginInline: "auto"
      }}>
        <h2>AI Crypto Chat</h2>
        <p>Ask anything about crypto markets.</p>

        <textarea
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Ask RoboDegen..."
          style={{
            width: "100%",
            height: "120px",
            padding: "15px",
            background: "#171226",
            color: "white",
            border: "1px solid #7e22ce",
            borderRadius: "12px"
          }}
        />

        <button style={{
          marginTop: "15px",
          padding: "12px 25px",
          background: "#9333ea",
          color: "white",
          border: "none",
          borderRadius: "8px"
        }}>
          Send Message
        </button>
      </div>
    </main>
  );
}